var chartdogio2457_1 = $('#chartdogio2457_1');
if (chartdogio2457_1.length) {
    $.post('/kttv/report/huonggio?hour=', { 'sdid': 2457},
        function (item) {
            if (item != "") {
                chartdogio2457_1.highcharts(
                    {
                        data: { "csv": item },
                        chart: { polar: true, type: 'column' },
                        title: { text: 'TỶ LỆ HƯỚNG GIÓ VÀ CƯỜNG ĐỘ GIÓ' },
                        subtitle: { text: null },
                        pane: { size: '85%' },
                        legend: { align: 'left', verticalAlign: 'top', y: 50, layout: 'vertical' },
                        xAxis: { tickmarkPlacement: 'on' },
                        yAxis: {
                            min: 0, endOnTick: false, showLastLabel: true, title: { text: 'Tỷ lệ (%)' }, labels: {
                                formatter: function () {
                                    return this.value + '%';
                                }
                            },
                            reversedStacks: false
                        },
                        tooltip: { valueSuffix: '%' },
                        plotOptions: {
                            series: {
                                stacking: 'normal',
                                shadow: false,
                                groupPadding: 0,
                                pointPlacement: 'on'
                            }
                        }
                    });
            }
        });
}

var chartdogio2457_2 = $('#chartdogio2457_2');
if (chartdogio2457_2.length) {
    $.post('/kttv/report/tocdogio?hour=', {'sdid': 2457},
        function (item) {
            if (item == null) return; if (item.err == 0) {
                chartdogio2457_2.highcharts({
                    title: { text: 'BIỀU ĐỒ HƯỚNG GIÓ VÀ TỐC ĐỘ GIÓ' },
                    xAxis: { type: 'datetime', offset: 40 },
                    plotOptions: { series: { pointStart: item.data[0].l[0], pointInterval: 600000 } },
                    series: [{
                        type: 'windbarb',
                        //key: ['x'],
                        data: item.data[0].data,
                        name: 'Hướng gió',
                        color: bgDanger,
                        showInLegend: false,
                        tooltip: {
                            valueSuffix: ' độ'
                        }
                    }, {
                        type: 'area',
                        keys: ['y', 'rotation'],
                        data: item.data[0].data,
                        color: bgSuccess,
                        name: 'Tốc độ gió',
                        tooltip: {
                            valueSuffix: ' m/s'
                        }
                    }]
                });
            }
        }, 'json').fail(function () {
            console.log("Có lỗi trong quá trình gửi dữ liệu!");
        });
}

