var stationid = 33
var localtime = 1789639800;
var realtime = 1789640088;
for (var i = 0; i < 48; i++) {
    $('#tbody').append($('#tempDevice').html().format(localtime, '', Unix_timestamp(localtime)));
    localtime -= 600;
}

window.setInterval(function () {
    realtime++;
    if (realtime % 600 == 0) {
        $('#tbody').prepend($('#tempDevice').html().format(realtime, '', Unix_timestamp(realtime)));
        //console.log('...');
    }
    //console.log(realtime);
}, 1000);

